(function(root){
  'use strict';
  const products=[
    ['Leche fresca','🥛','#d9e9ed','La Vaquita'],['Queso fresco','🧀','#f7e5ad','Mercado Central'],
    ['Yogurt','🥣','#eddff0','Café Aurora'],['Mantequilla','🧈','#f7d8b7','Panadería Alba'],
    ['Leche chocolatada','🍫','#e3d3c8','Colegio El Roble'],['Helado','🍦','#d6e8d4','Heladería Nube'],
    ['Yogurt griego','🥣','#dce0f4','Club Vital'],['Kumis','🥛','#dcebd0','Tienda del Barrio'],
    ['Postre lácteo','🍮','#f5dadd','Restaurante Oliva'],['Queso madurado','🧀','#f0dfb1','Bistró Norte'],
    ['Bebida fermentada','🧃','#d9e9e2','Eco Mercado']
  ];
  // Tuple: product index, processing time, due date, release date, weight.
  const jobs=(rows)=>rows.map(([k,p,d=240,r=0,w=1],i)=>({id:'J'+(i+1),product:products[k][0],icon:products[k][1],color:products[k][2],client:products[k][3],p,d,r,w}));
  const worlds=[
    {id:1,name:'Primer día',place:'Recepción de leche',icon:'🥛',color:'sage',description:'Conoce tus pedidos. Encuentra tu ritmo.',ids:[1,2,3,4]},
    {id:2,name:'A contrarreloj',place:'Sala de producción',icon:'⏱',color:'gold',description:'Llegadas, descansos y promesas por cumplir.',ids:[5,6,7,8]},
    {id:3,name:'Doble capacidad',place:'Centro de distribución',icon:'⚙',color:'blue',description:'Más máquinas. Nuevas decisiones.',ids:[9,10,11,12]}
  ];
  const definitions=[
    {id:1,world:1,title:'Tu primer turno',tag:'Tutorial',objective:'makespan',mission:'Nuestra primera máquina está lista. Organiza los tres pedidos y despacha la producción.',jobs:jobs([[0,15],[1,30],[2,20]]),show:[],lesson:'En una máquina, con todos los pedidos disponibles y sin descansos, Cmax es la suma de sus duraciones. Todos los órdenes terminan a los 65 minutos. ¡En la siguiente misión, el orden sí importa!',hints:['Cada tarjeta es un pedido. El número de minutos indica cuánto ocupa la máquina.','La máquina procesa un pedido a la vez. Coloca los tres en su cola.','No hay pausas ni llegadas tardías: cualquier orden termina a los 65 min.']},
    {id:2,world:1,title:'Pequeños primero',tag:'Secuenciación',objective:'total-completion-time',mission:'La tienda del barrio tiene fila. Consigue que los pedidos terminen pronto, en conjunto.',jobs:jobs([[1,35],[0,10],[3,25],[2,15]]),show:[],lesson:'Un pedido largo al principio retrasa a todos los siguientes. Con disponibilidad inicial y sin restricciones, SPT (menor duración primero) minimiza ΣCj.',hints:['Lo que tarda el primer pedido también lo esperan todos los siguientes.','Prueba comenzar con los pedidos que terminan más rápido.','SPT: ordena de menor a mayor duración. Comienza por J2 y después J4.']},
    {id:3,world:1,title:'Una promesa es una promesa',tag:'Entregas',objective:'total-tardiness',mission:'Cada cliente tiene una hora prometida. Reduce la suma de los minutos de retraso.',jobs:jobs([[1,30,60],[0,10,20],[4,15,35],[2,20,55]]),show:['d'],lesson:'Tj cuenta únicamente minutos de retraso; una entrega anticipada no compensa una tardía. EDD (fecha de entrega primero) es una pista útil, pero no garantiza minimizar ΣTj en general.',hints:['Compara la duración de cada pedido con la hora prometida.','Una entrega temprana no borra el retraso de otra. Mira qué compromisos vencen primero.','Prueba EDD: menor fecha de entrega primero. En otros escenarios podría convenir un orden distinto.']},
    {id:4,world:1,title:'Clientes que cuentan',tag:'Prioridades',objective:'weighted-completion',mission:'El colegio necesita su pedido. Reduce la espera dando más importancia a los clientes prioritarios.',jobs:jobs([[1,30,150,0,2],[4,20,150,0,5],[0,10,150,0,2],[6,25,150,0,3]]),show:['w'],lesson:'Para minimizar ΣwjCj en este escenario básico, compara duración / prioridad. WSPT ordena de menor a mayor pj/wj; una prioridad alta por sí sola no basta.',hints:['Las estrellas representan importancia: cada minuto de espera se multiplica por esa prioridad.','Busca mucho valor para el cliente con pocos minutos de máquina.','WSPT: ordena por pj/wj de menor a mayor. J2 tiene la menor razón: 20/5 = 4.']},
    {id:5,world:2,title:'El camión de las nueve',tag:'Disponibilidad',objective:'total-completion-time',mission:'La materia prima llega por tandas. Aprovecha el tiempo mientras esperas los siguientes pedidos.',jobs:jobs([[1,35,160,0],[0,10,90,25],[7,20,100,0],[2,15,130,60],[3,25,150,35]]),show:['r','d'],lesson:'Un pedido no puede comenzar antes de rj. El motor respeta tu cola: si eliges uno que no ha llegado, la máquina espera. Fj mide desde su llegada; Cj se mide desde las 08:00.',hints:['Las tarjetas muestran desde cuándo está disponible cada pedido.','Colocar un pedido todavía no disponible al frente puede dejar la máquina esperando.','Compara J1 → J2 con J3 → J2: un trabajo corto no siempre conviene si aún no ha llegado.']},
    {id:6,world:2,title:'Antes del café',tag:'Descansos',objective:'makespan',jobs:jobs([[1,45,240],[0,10,240],[2,30,240],[3,35,240],[7,20,240]]),show:['d'],breaks:[{start:120,end:140,label:'Café'}],mission:'A las 10:00 hay una pausa de 20 minutos. Ningún proceso puede quedar a medias. Aprovecha los huecos.',lesson:'Los trabajos no se interrumpen. Si un pedido no cabe antes de la pausa, empieza después. Terminar exactamente a las 10:00 sí está permitido.',hints:['La zona rayada es una pausa obligatoria: ningún pedido puede atravesarla.','Intenta sumar 120 minutos antes de la pausa para no dejar un hueco.','45 + 35 + 30 + 10 = 120. Deja el pedido de 20 minutos para después del café.']},
    {id:7,world:2,title:'Quince minutos de ventaja',tag:'Elige bien',objective:'total-tardiness',jobs:jobs([[1,30,180,105],[0,10,120,105],[2,40,70],[4,25,100,40],[8,20,170,90]]),show:['r','d'],breaks:[{start:120,end:140,label:'Café'}],mission:'Son las 09:45 cuando llegan leche y queso. Uno cabe antes del descanso. El otro tendrá que esperar.',lesson:'A las 09:45 quedan 15 minutos hasta la pausa. El pedido de 10 minutos puede terminar; el de 30 no. Duración, llegada y entrega deben leerse juntas.',hints:['Hay dos pedidos que llegan a las 09:45. ¿Cuál cabe en 15 minutos?','Reservar la máquina para un trabajo largo puede impedir una entrega corta a tiempo.','Intenta J3 → J4 → J5 → J2 → J1. Luego compara los retrasos.']},
    {id:8,world:2,title:'La ruta del colegio',tag:'Turno completo',objective:'weighted-tardiness',jobs:jobs([[4,20,110,70,5],[1,40,130,0,2],[0,15,55,0,2],[6,30,150,30,3],[3,25,115,0,1],[8,20,180,100,2]]),show:['r','d','w'],breaks:[{start:90,end:110,label:'Limpieza'}],mission:'El transporte escolar sale pronto. Cuida los pedidos prioritarios sin olvidar la limpieza de la línea.',lesson:'ΣwjTj combina retraso e importancia. Un minuto de retraso con peso 5 cuesta lo mismo que cinco minutos con peso 1. Las entregas son metas, no restricciones duras.',hints:['La limpieza impide producir de 09:30 a 09:50.','El pedido del colegio llega a las 09:10: puede terminar justo antes de la limpieza.','Prueba reservar el hueco 09:10–09:30 para J1; luego compara las otras prioridades.']},
    {id:9,world:3,title:'Mejor en equipo',tag:'Dos máquinas',mode:'parallel-identical',machines:2,objective:'makespan',jobs:jobs([[1,40,150],[0,15,100],[2,25,120],[3,30,140],[7,20,120]]),show:[],mission:'Estrenamos otro pasteurizador. Reparte los pedidos entre A y B para terminar toda la producción pronto.',lesson:'En máquinas idénticas puedes elegir tanto la asignación como el orden. El fin de producción es el mayor tiempo de finalización entre todas las máquinas.',hints:['Dos máquinas pueden trabajar a la vez. Evita que una se quede con casi toda la carga.','El total es 130 minutos. Dividirlo entre dos da una cota inferior de 65.','Busca dos grupos de 65: 40 + 25 y 30 + 20 + 15.']},
    {id:10,world:3,title:'El equilibrio perfecto',tag:'Balance de carga',mode:'parallel-identical',machines:2,objective:'load-balance',jobs:jobs([[1,35,180],[0,10,180],[2,25,180],[3,30,180],[5,40,180],[7,20,180]]),show:[],mission:'Reparte el esfuerzo. Acerca los minutos de trabajo de ambas máquinas tanto como puedas.',lesson:'La carga suma los minutos de procesamiento de una máquina. El objetivo es carga máxima − carga mínima; las pausas y la espera no cuentan como trabajo.',hints:['Contar pedidos no es lo mismo que contar minutos de trabajo.','La producción suma 160 minutos: intenta asignar 80 a cada máquina.','35 + 25 + 20 = 80. El resto también suma 80.']},
    {id:11,world:3,title:'Tres líneas, cero excusas',tag:'Tres máquinas',mode:'parallel-identical',machines:3,objective:'late-jobs',jobs:jobs([[1,40,50],[0,15,25],[4,20,40,10],[2,30,65],[5,45,80,15],[10,25,60]]),show:['r','d'],mission:'Ahora hay tres líneas. Consigue que la mayor cantidad posible de pedidos llegue a tiempo.',lesson:'Aquí cuenta el número de pedidos tardíos, no cuánto se retrasan. Un pedido con un minuto de tardanza cuenta igual que uno con veinte.',hints:['Reparte primero los compromisos que vencen temprano.','Una máquina libre puede recibir un pedido recién llegado mientras las otras siguen produciendo.','Prueba A: J1 → J4; B: J2 → J5; C: J3 → J6. ¿Puedes evitar la entrega tardía que queda?']},
    {id:12,world:3,title:'Maestría láctea',tag:'Misión final',mode:'parallel-identical',machines:3,objective:'weighted-tardiness',jobs:jobs([[4,25,45,10,5],[1,45,65,0,2],[0,15,30,0,3],[6,35,80,25,4],[5,50,100,20,2],[8,30,70,15,3]]),show:['r','d','w'],breaks:[{start:50,end:70,label:'Limpieza A',machine:0},{start:70,end:90,label:'Limpieza B',machine:1},{start:90,end:110,label:'Limpieza C',machine:2}],mission:'Coordina tres máquinas con limpiezas escalonadas. Protege las entregas de mayor prioridad y cierra tu mejor turno.',lesson:'Combina disponibilidad, duración, prioridad y calendario de cada máquina. Una regla aislada ya no basta: mueve un pedido, observa el Gantt y compara el objetivo.',hints:['Cada máquina tiene su propia ventana de limpieza.','Los pedidos largos necesitan una ventana continua. Comprueba dónde cabe el helado.','Reserva pronto una máquina para J5 y otra para J1. Prioriza después el peso y la fecha de cada pedido.']}
  ];
  const levels=definitions.map(l=>({mode:'single-machine',machines:1,breaks:[],abilities:[],events:[],startHour:8,...l}));
  const api={levels,worlds,products};root.DairyLevels=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
